  "Add a photo and bio from Edit profile. Posts here come from feeds you follow.": "\"प्रोफ़ाइल एडिट करें\" से फ़ोटो और बायो जोड़ें। यहाँ की पोस्ट आपकी फ़ॉलो की गई फ़ीड से आती हैं।",
  "Language and appearance stay on this device.": "भाषा और दिखावट इसी डिवाइस पर रहती हैं।",
  "Account settings are available after you sign in.": "अकाउंट सेटिंग्स साइन इन करने के बाद उपलब्ध होती हैं।",
  "This app is a reader for posts from feeds you follow. Not affiliated with X.": "यह ऐप आपकी फ़ॉलो की गई फ़ीड की पोस्ट पढ़ने के लिए है। X से संबद्ध नहीं।",
  "Sign in with the 16-digit account number from sign-up. It is shown once. There is no password to reset.": "साइन-अप के समय मिले 16 अंकों के अकाउंट नंबर से साइन इन करें। यह सिर्फ़ एक बार दिखाया जाता है। रीसेट करने के लिए कोई पासवर्ड नहीं है।",
  "The account number is your login. The timeline shows posts from feeds. Not affiliated with X.": "अकाउंट नंबर ही आपका लॉगिन है। टाइमलाइन फ़ीड की पोस्ट दिखाती है। X से संबद्ध नहीं।",
  "The account number is stored as a hash. There is no email on the account. Settings stay on this device.": "अकाउंट नंबर हैश के रूप में रखा जाता है। अकाउंट में कोई ईमेल नहीं है। सेटिंग्स इसी डिवाइस पर रहती हैं।",
  "This app does not use tracking cookies. The session and settings stay in this browser.": "यह ऐप ट्रैकिंग कुकीज़ इस्तेमाल नहीं करता। सेशन और सेटिंग्स इसी ब्राउज़र में रहती हैं।",
  "Fields have labels. Tab moves between them, Enter continues, and Escape closes a dialog.": "फ़ील्ड पर लेबल हैं। Tab से उनके बीच जाएँ, Enter से आगे बढ़ें और Escape से डायलॉग बंद करें।",
