  "Stays on this device only. Use a spare account. Discord may lock accounts used this way.": "सिर्फ़ इसी डिवाइस पर रहती है। स्पेयर अकाउंट इस्तेमाल करें। Discord इस तरह इस्तेमाल होने वाले अकाउंट लॉक कर सकता है।",
  "That doesn’t look like a Discord key.": "यह Discord की जैसी नहीं लगती।",
