  "The check couldn’t load here. Open the invite in the Discord app with the spare account instead.": "जाँच यहाँ लोड नहीं हो सकी। इसके बजाय स्पेयर अकाउंट से Discord ऐप में इनवाइट खोलें।",
  "The check expired. Solve it again.": "जाँच एक्सपायर हो गई। इसे फिर से हल करें।",
  "This account can’t read that channel.": "यह अकाउंट वह चैनल नहीं पढ़ सकता।",
