  "This account isn’t in any servers yet.": "यह अकाउंट अभी किसी सर्वर में नहीं है।",
  "This browser can’t keep keys safely.": "यह ब्राउज़र की सुरक्षित नहीं रख सकता।",
  "This key needs replacing. Discord signed it out, so reads are paused. Paste a new key from the spare account.": "इस की को बदलना होगा। Discord ने इसे साइन आउट कर दिया, इसलिए पढ़ना रुका है। स्पेयर अकाउंट की नई की पेस्ट करें।",
  "Wait {n} seconds before joining another server.": "दूसरे सर्वर से जुड़ने से पहले {n} सेकंड रुकें।",
  "Discord asked to wait. You can send again in {n} seconds.": "Discord ने रुकने को कहा है। {n} सेकंड बाद फिर भेज सकते हैं।",
  "Discord didn’t accept that message.": "Discord ने यह मैसेज स्वीकार नहीं किया।",
  "Discord didn’t open a chat with this person.": "Discord ने इस व्यक्ति के साथ चैट नहीं खोली।",
  "Discord wants a quick check before this message goes out.": "यह मैसेज भेजने से पहले Discord एक छोटी जाँच चाहता है।",
  "Discord won’t deliver messages to this person from this account.": "Discord इस अकाउंट से इस व्यक्ति को मैसेज नहीं पहुँचाएगा।",
  "Message not sent. Check your connection and tap Try again.": "मैसेज नहीं भेजा गया। अपना कनेक्शन जाँचें और फिर से कोशिश करें पर टैप करें।",
  "Message {name}": "{name} में मैसेज",
  "Messages can be up to {n} characters.": "मैसेज ज़्यादा से ज़्यादा {n} अक्षरों का हो सकता है।",
  "Messages you post here go out from the spare account, one tap at a time.": "यहाँ से भेजे गए मैसेज स्पेयर अकाउंट से जाते हैं, हर टैप पर एक।",
  "Not sent.": "नहीं भेजा गया।",
  "One message at a time. Try again in a moment.": "एक बार में एक मैसेज। थोड़ी देर में फिर कोशिश करें।",
  "Opening…": "खुल रहा है…",
  "Sending…": "भेजा जा रहा है…",
  "Solve it yourself to send your message. Nothing solves it for you.": "अपना मैसेज भेजने के लिए इसे खुद हल करें। इसे आपके लिए कोई हल नहीं करता।",
  "Start a direct message with this person from the spare account.": "स्पेयर अकाउंट से इस व्यक्ति को डायरेक्ट मैसेज शुरू करें।",
  "That’s a lot of messages this minute. You can send again in {n} seconds.": "इस मिनट में काफ़ी मैसेज हो गए। {n} सेकंड बाद फिर भेज सकते हैं।",
  "The check couldn’t load here. Send this message in the Discord app instead.": "जाँच यहाँ लोड नहीं हो सकी। यह मैसेज Discord ऐप से भेजें।",
  "This account can’t send messages here.": "यह अकाउंट यहाँ मैसेज नहीं भेज सकता।",
  "Wait {n} seconds before opening another chat.": "दूसरी चैट खोलने से पहले {n} सेकंड रुकें।",
  "You can read and send messages here as the spare account. Every message is one you type and send yourself. Discord may flag automated or self-bot use, so keep it to a spare account.": "यहाँ आप स्पेयर अकाउंट से मैसेज पढ़ और भेज सकते हैं। हर मैसेज आप खुद लिखते और भेजते हैं। Discord ऑटोमेटेड या सेल्फ़-बॉट इस्तेमाल को फ़्लैग कर सकता है, इसलिए इसे स्पेयर अकाउंट तक ही रखें।",
  "Paste keys from your own accounts. They stay encrypted, and the saved value is never shown again.": "अपने अकाउंट की कीज़ पेस्ट करें। वे एन्क्रिप्ट रहती हैं, और सेव की गई वैल्यू फिर कभी नहीं दिखाई जाती।",
  "Keys from your own accounts stay encrypted.": "आपके अपने अकाउंट की कीज़ एन्क्रिप्ट रहती हैं।",
  "In your own browser, while you are signed in, export cookies as a Netscape cookies.txt file or copy the Cookie header from one request you made to that site.": "अपने ब्राउज़र में, साइन इन रहते हुए, कुकीज़ को Netscape cookies.txt फ़ाइल के रूप में एक्सपोर्ट करें या उस साइट पर किए गए किसी एक अनुरोध से Cookie हेडर कॉपी करें।",
  "Paste a Cookie header or a Netscape cookies.txt file.": "Cookie हेडर या Netscape cookies.txt फ़ाइल पेस्ट करें।",
  "Paste the client id and the client secret from your own app, one on each line.": "अपने ऐप की client id और client secret पेस्ट करें, हर एक अलग लाइन में।",
  "Paste the token from your own account.": "अपने अकाउंट का टोकन पेस्ट करें।",
