  "Setup needed": "सेटअप ज़रूरी है",
  "Delete account": "अकाउंट डिलीट करें",
  "Permanently delete this account and the data tied to it.": "यह अकाउंट और इससे जुड़ा डेटा हमेशा के लिए डिलीट करें।",
  "This permanently deletes this account. Your profile, photos, sessions, follows, followers, friends, notification tabs, feed settings, groups, drafts, likes, bookmarks, watch history, community posts, vault, drive files, linked accounts, and uploads are removed. The handle can stay reserved so nobody else can take it. This cannot be undone.": "इससे यह अकाउंट हमेशा के लिए डिलीट हो जाता है। आपकी प्रोफ़ाइल, फ़ोटो, सेशन, फ़ॉलो, फ़ॉलोअर, दोस्त, नोटिफ़िकेशन टैब, फ़ीड सेटिंग्स, ग्रुप, ड्राफ़्ट, लाइक, बुकमार्क, देखने की हिस्ट्री, कम्युनिटी पोस्ट, वॉल्ट, ड्राइव फ़ाइलें, लिंक किए गए अकाउंट और अपलोड हटा दिए जाते हैं। हैंडल रिज़र्व रह सकता है ताकि कोई और उसे न ले सके। इसे वापस नहीं लिया जा सकता।",
  "Enter your account number again.": "अपना अकाउंट नंबर फिर से डालें।",
  "Confirm your handle": "अपना हैंडल कन्फ़र्म करें",
  "The handle does not match.": "हैंडल मेल नहीं खाता।",
  "The account number does not match.": "अकाउंट नंबर मेल नहीं खाता।",
  "This account cannot be deleted.": "यह अकाउंट डिलीट नहीं किया जा सकता।",
  "Deleting your account": "आपका अकाउंट डिलीट हो रहा है",
  "Checking your account": "आपका अकाउंट चेक हो रहा है",
  "Removing the account": "अकाउंट हटाया जा रहा है",
  "Removing saved files": "सेव की गई फ़ाइलें हटाई जा रही हैं",
