  "That handle is not available yet.": "यह हैंडल अभी उपलब्ध नहीं है।",
  "Deletion did not finish. Try again.": "डिलीट करना पूरा नहीं हुआ। फिर से कोशिश करें।",
  "Add another key": "एक और की जोड़ें",
  "Optional label": "वैकल्पिक लेबल",
  "Key label": "की का लेबल",
  "Keys are backups. One key is used at a time, highest priority first.": "कीज़ बैकअप हैं। एक समय में एक ही की इस्तेमाल होती है, सबसे ऊँची प्राथमिकता वाली पहले।",
  "Slowing down": "धीमा हो रहा है",
  "This service is slowing down. The same key stays in use.": "यह सर्विस धीमी हो रही है। वही की इस्तेमाल होती रहेगी।",
  "{service} is slowing down. The same key stays in use.": "{service} धीमी हो रही है। वही की इस्तेमाल होती रहेगी।",
