  "Photos and banners are visible to everyone until you change one.": "जब तक आप बदलते नहीं, फ़ोटो और बैनर सभी को दिखते हैं।",
  "A private account starts photos and banners at followers.": "निजी अकाउंट में फ़ोटो और बैनर शुरू में सिर्फ़ फ़ॉलोअर को दिखते हैं।",
  "Facebook has no public feed we can read without a paid API.": "Facebook की कोई ऐसी पब्लिक फ़ीड नहीं है जिसे हम पेड API के बिना पढ़ सकें।",
