  "Discord server. Add opens Add Discord.": "Discord सर्वर। जोड़ें दबाने पर Discord जोड़ें खुलेगा।",
  "Discord is busy right now. Try again in {seconds} s.": "Discord अभी व्यस्त है। {seconds} सेकंड बाद फिर कोशिश करें।",
  "Discord didn’t accept that check. Solve the new one, or open the invite in Discord.": "Discord ने वह जाँच स्वीकार नहीं की। नई जाँच हल करें या आमंत्रण Discord में खोलें।",
  "The check expired. Solve it again.": "जाँच की समय-सीमा खत्म हो गई। इसे फिर से हल करें।",
  "The check couldn’t load here. Open the invite in Discord with the spare account instead.": "जाँच यहाँ लोड नहीं हो सकी। अतिरिक्त खाते से आमंत्रण Discord में खोलें।",
  "That check expired before Discord got it. Open the invite in Discord, or try joining again.": "Discord तक पहुँचने से पहले जाँच की समय-सीमा खत्म हो गई। आमंत्रण Discord में खोलें या फिर से जुड़ने की कोशिश करें।",
  "Discord didn’t accept it. Open the invite in Discord with the spare account, then press Check again.": "Discord ने इसे स्वीकार नहीं किया। अतिरिक्त खाते से आमंत्रण Discord में खोलें, फिर “फिर से जाँचें” दबाएँ।",
  "Quick check from Discord": "Discord की त्वरित जाँच",
  "Solve it yourself to finish joining. Your answer is sent to Discord once.": "जुड़ना पूरा करने के लिए इसे खुद हल करें। आपका उत्तर Discord को एक बार भेजा जाता है।",
