  "Discord asked for a captcha. Open the invite in the Discord app with the spare account, join there, then press Check again.": "Discord ने कैप्चा माँगा। अतिरिक्त खाते से Discord ऐप में इनवाइट खोलें, वहाँ जुड़ें, फिर “फिर से जाँचें” दबाएँ।",
  "The source asked us to slow down. We’ll try again later.": "सोर्स ने हमें धीमा होने को कहा। हम बाद में फिर कोशिश करेंगे।",
