  "Last used {date}": "आखिरी इस्तेमाल {date}",
  "Remove this passkey?": "यह पासकी हटाएँ?",
  "A passkey uses this device's fingerprint, face, or screen lock. No password is required. The account number still works as an optional backup.": "पासकी इस डिवाइस के फ़िंगरप्रिंट, फ़ेस या स्क्रीन लॉक का इस्तेमाल करती है। पासवर्ड की ज़रूरत नहीं होती। अकाउंट नंबर अब भी वैकल्पिक बैकअप के रूप में काम करता है।",
  "Passkeys stay on the site where you created them. A passkey made on one site does not sign in on the other.": "पासकी उसी साइट पर रहती हैं जहाँ आपने उन्हें बनाया। एक साइट पर बनी पासकी दूसरी साइट पर साइन इन नहीं करती।",
  "Choose a phone or tablet when you want a QR code for cross-device sign-in.": "दूसरे डिवाइस से साइन इन के लिए QR कोड चाहिए तो फ़ोन या टैबलेट चुनें।",
  "No passkeys on this site yet.": "इस साइट पर अभी कोई पासकी नहीं।",
  "Add a passkey": "पासकी जोड़ें",
  "Covered": "ढका हुआ",
  "Privacy screen": "प्राइवेसी स्क्रीन",
  "Cover the app when this window is hidden, in the background, or locked.": "जब यह विंडो छिपी हो, बैकग्राउंड में हो या लॉक हो, तब ऐप को ढक दें।",
  "Messages only": "सिर्फ़ मैसेज",
  "Whole app": "पूरा ऐप",
  "The cover is one layer. It does not blur, hide, or restyle the page, and it goes away when this window is in front.": "यह कवर एक परत है। यह पेज को धुंधला, छिपा या बदलता नहीं है, और विंडो सामने आते ही हट जाता है।",
  "Android can block screenshots only in a wrapper that sets FLAG_SECURE. This site does not include that wrapper.": "Android सिर्फ़ उसी रैपर में स्क्रीनशॉट ब्लॉक कर सकता है जो FLAG_SECURE सेट करता है। इस साइट में वह रैपर शामिल नहीं है।",
  "Stop text selection in messages": "मैसेज में टेक्स्ट चुनना बंद करें",
  "Unlock to open the app": "ऐप खोलने के लिए अनलॉक करें",
  "The sensor encrypts drafts, messages, and the on-device copy. Unlock works with no internet.": "सेंसर ड्राफ़्ट, मैसेज और डिवाइस पर रखी कॉपी को एन्क्रिप्ट करता है। अनलॉक बिना इंटरनेट के भी काम करता है।",
  "This browser cannot tie encryption to the sensor. The sensor approves unlock, and the PIN encrypts data on this device. A person with the PIN and a copy of this storage can decrypt it without the sensor.": "यह ब्राउज़र एन्क्रिप्शन को सेंसर से नहीं जोड़ सकता। सेंसर अनलॉक की मंज़ूरी देता है, और PIN इस डिवाइस का डेटा एन्क्रिप्ट करता है। जिसके पास PIN और इस स्टोरेज की कॉपी हो, वह सेंसर के बिना इसे डिक्रिप्ट कर सकता है।",
  "Device PIN": "डिवाइस PIN",
  "Unlock": "अनलॉक करें",
  "Forgot": "भूल गए",
  "This signs you out and erases drafts, messages, and other data saved on this device.": "इससे आप साइन आउट हो जाएँगे और इस डिवाइस पर सेव किए गए ड्राफ़्ट, मैसेज और दूसरा डेटा मिट जाएगा।",
  "Erase and sign out": "मिटाएँ और साइन आउट करें",
  "App lock": "ऐप लॉक",
  "Lock when the app opens": "ऐप खुलते ही लॉक करें",
  "Lock after time in the background": "बैकग्राउंड में कुछ समय बाद लॉक करें",
