  "Confirm the PIN": "PIN कन्फ़र्म करें",
  "Lock now": "अभी लॉक करें",
  "Turn off app lock": "ऐप लॉक बंद करें",
  "Set up app lock": "ऐप लॉक सेट अप करें",
  "Could not create a passkey.": "पासकी नहीं बन सकी।",
  "Those PINs do not match.": "ये PIN मेल नहीं खाते।",
  "Use at least 4 characters.": "कम से कम 4 कैरेक्टर इस्तेमाल करें।",
  "Too many attempts. Wait and try again.": "बहुत ज़्यादा कोशिशें। थोड़ा रुककर फिर से कोशिश करें।",
  "Wrong PIN or the sensor was not recognized.": "गलत PIN या सेंसर ने पहचाना नहीं।",
  "Save this account number. You can sign in with a passkey later. The number is an optional backup.": "यह अकाउंट नंबर सेव कर लें। बाद में आप पासकी से साइन इन कर सकते हैं। यह नंबर एक वैकल्पिक बैकअप है।",
  "Create a passkey": "पासकी बनाएँ",
  "Continue without a passkey": "पासकी के बिना जारी रखें",
  "Sign in with a passkey": "पासकी से साइन इन करें",
  "Could not verify that passkey.": "वह पासकी वेरिफ़ाई नहीं हो सकी।",
  "There is no password to reset. A passkey can sign in, and the account number from sign-up still works.": "रीसेट करने के लिए कोई पासवर्ड नहीं है। पासकी से साइन इन हो सकता है, और साइन-अप के समय मिला अकाउंट नंबर भी काम करता है।",
  "On-device AI": "ऑन-डिवाइस AI",
  "Language detection and the spam filter are included. Larger downloads stay off until you turn them on. They wait for Wi-Fi, a battery that is not low, and data saver to be off.": "भाषा पहचान और स्पैम फ़िल्टर शामिल हैं। बड़े डाउनलोड तब तक बंद रहते हैं जब तक आप उन्हें चालू नहीं करते। वे वाई-फ़ाई, ठीक-ठाक बैटरी और डेटा सेवर बंद होने का इंतज़ार करते हैं।",
  "Detect language on this device": "इस डिवाइस पर भाषा पहचानें",
  "Included. No download. The browser detector is used when it exists.": "शामिल है। कोई डाउनलोड नहीं। जहाँ ब्राउज़र डिटेक्टर उपलब्ध हो, वह इस्तेमाल होता है।",
  "Hide likely spam": "संभावित स्पैम छिपाएँ",
  "Included. No download. Replies, messages, and notifications stay hidden behind Show.": "शामिल है। कोई डाउनलोड नहीं। जवाब, मैसेज और नोटिफ़िकेशन \"दिखाएँ\" के पीछे छिपे रहते हैं।",
  "Summaries on this device": "इस डिवाइस पर सारांश",
  "Included. No download. Long posts, threads, unread messages, and Catch me up use this device first.": "शामिल है। कोई डाउनलोड नहीं। लंबी पोस्ट, थ्रेड, बिना पढ़े मैसेज और \"मुझे अपडेट करें\" पहले यही डिवाइस इस्तेमाल करते हैं।",
  "Compose help on this device": "इस डिवाइस पर लिखने में मदद",
  "Included. No download. Suggestions, grammar, and tone stay here unless you allow a server.": "शामिल है। कोई डाउनलोड नहीं। सुझाव, ग्रामर और टोन यहीं रहते हैं, जब तक आप सर्वर को अनुमति न दें।",
  "Search saved posts by meaning": "सेव की गई पोस्ट को मतलब से सर्च करें",
  "Off until you turn it on. The included ranker needs no download.": "चालू करने तक बंद। शामिल रैंकर को किसी डाउनलोड की ज़रूरत नहीं।",
  "Download a search model": "सर्च मॉडल डाउनलोड करें",
  "About {size}. Apache-2.0. Off until you turn it on.": "लगभग {size}। Apache-2.0। चालू करने तक बंद।",
  "About {size}, plus a small runtime that is cached after the first download. Apache-2.0. Off until you turn it on.": "लगभग {size}, साथ में एक छोटा रनटाइम जो पहली बार डाउनलोड होने के बाद कैश हो जाता है। Apache-2.0। चालू करने तक बंद।",
