  "The timeline, stories, notes, live video, and gifts. It runs in the browser and as an installed app.": "टाइमलाइन, स्टोरीज़, नोट्स, लाइव वीडियो और तोहफ़े। यह ब्राउज़र में और इंस्टॉल किए गए ऐप के रूप में चलता है।",
  "A familiar timeline": "जानी-पहचानी टाइमलाइन",
  "For you and Following, in a dark layout built for scrolling.": "\"आपके लिए\" और \"फ़ॉलोइंग\", स्क्रॉल करने के लिए बने डार्क लेआउट में।",
