  "Gifts from the store": "स्टोर से तोहफ़े",
  "ViktorychStore lists gifts you can send. Points come from using the app. Nothing is for sale.": "ViktorychStore में वे तोहफ़े हैं जो आप भेज सकते हैं। पॉइंट ऐप इस्तेमाल करने से मिलते हैं। कुछ भी बिकाऊ नहीं है।",
