  "Messages, online status and typing go straight to friends who are online, and media they already loaded can come from their device. Friends can see your IP address while connected. Messages written offline are sent when you’re back online.": "मैसेज, ऑनलाइन स्टेटस और टाइपिंग सीधे ऑनलाइन दोस्तों तक जाते हैं, और जो मीडिया उन्होंने पहले लोड किया है, वह उनके डिवाइस से आ सकता है। कनेक्ट रहते समय दोस्त आपका IP पता देख सकते हैं। ऑफ़लाइन लिखे मैसेज ऑनलाइन वापस आने पर भेजे जाते हैं।",
  "You’re offline. It will send when you’re back online.": "आप ऑफ़लाइन हैं। ऑनलाइन वापस आने पर यह भेजा जाएगा।",
