  "Servers": "सर्वर",
  "Controller connected, but ReGone doesn't support controllers yet. Use touch, or keyboard and mouse.": "कंट्रोलर कनेक्ट हो गया, लेकिन ReGone अभी कंट्रोलर सपोर्ट नहीं करता। टच या कीबोर्ड और माउस से खेलें।",
  "Add Discord": "Discord जोड़ें",
