  "Joined. Pick the channels to show.": "जॉइन हो गया। दिखाने के लिए चैनल चुनें।",
  "This server can’t be joined that way. Discord asked for a captcha or verification.": "इस सर्वर को इस तरह जॉइन नहीं किया जा सकता। Discord ने कैप्चा या वेरिफ़िकेशन माँगा।",
  "Couldn’t join that server.": "वह सर्वर जॉइन नहीं हो सका।",
