  "Couldn’t look up that invite.": "वह इनवाइट जाँचा नहीं जा सका।",
  "Join “{name}” with the spare Discord account? One server only.": "“{name}” को अतिरिक्त Discord अकाउंट से जॉइन करें? सिर्फ़ एक सर्वर।",
  "Confirm the join first.": "पहले जॉइन करने की पुष्टि करें।",
  "Wait a minute before joining another server.": "दूसरा सर्वर जॉइन करने से पहले एक मिनट रुकें।",
  "Couldn’t start the join.": "जॉइन शुरू नहीं हो सका।",
  "Joining… this usually takes under a minute.": "जॉइन हो रहा है… आमतौर पर एक मिनट से कम लगता है।",
  "Still waiting. Join with the spare account in Discord, then come back.": "अभी भी इंतज़ार है। Discord में अतिरिक्त अकाउंट से जॉइन करें, फिर वापस आएँ।",
  "Pick at least one channel.": "कम से कम एक चैनल चुनें।",
  "Couldn’t save those channels.": "वे चैनल सेव नहीं हो सके।",
  "Saved. Messages show up after the next sync.": "सेव हो गया। अगले सिंक के बाद मैसेज दिखेंगे।",
  "Remove this server from Messages?": "इस सर्वर को मैसेज से हटाएँ?",
  "{count} members": "{count} मेंबर",
  "The spare account is already in this server.": "अतिरिक्त अकाउंट पहले से इस सर्वर में है।",
  "Pick channels": "चैनल चुनें",
  "One tap joins with the spare Discord account. Discord may ask for a captcha; if so, this server can’t be joined that way.": "एक टैप में अतिरिक्त Discord अकाउंट से जॉइन होता है। Discord कैप्चा माँग सकता है; ऐसा हो तो इस सर्वर को इस तरह जॉइन नहीं किया जा सकता।",
  "Joining…": "जॉइन हो रहा है…",
