  "None listed yet. Press Check again after joining.": "अभी कोई सूची नहीं। जॉइन करने के बाद “फिर से जाँचें” दबाएँ।",
  "Asked the sync to re-list servers.": "सिंक से सर्वर फिर से सूचीबद्ध करने को कहा गया।",
  "Discord key stopped working, paste a new one": "Discord की चाबी काम नहीं कर रही, नई पेस्ट करें",
  "Smart Auto: media from sites that are blocked in your country, or that failed to load on this device, comes through our servers. Photos and videos keep their original quality.": "स्मार्ट ऑटो: जिन साइटों पर आपके देश में रोक है, या जो इस डिवाइस पर लोड नहीं हो सकीं, उनका मीडिया हमारे सर्वर से आता है। फ़ोटो और वीडियो की क्वालिटी पहले जैसी रहती है।",
  "{ms} ms": "{ms} मि.से.",
  "not reachable": "पहुँच से बाहर",
  "If the app is slow or won't load": "अगर ऐप धीमा है या लोड नहीं हो रहा",
  "The app keeps your feed on this device, so saved posts open even with a bad connection. When our main server stalls, it switches to the backup server by itself.": "ऐप आपकी फ़ीड इसी डिवाइस पर रखता है, इसलिए खराब कनेक्शन में भी सेव की गई पोस्ट खुलती हैं। जब हमारा मुख्य सर्वर अटकता है, तो ऐप अपने आप बैकअप सर्वर पर चला जाता है।",
  "Checking…": "जाँच हो रही है…",
  "Check connection": "कनेक्शन जाँचें",
  "In India": "भारत में",
  "Some internet providers block sites through DNS. Turning on secure DNS usually fixes it:": "कुछ इंटरनेट प्रोवाइडर DNS के ज़रिए साइटें ब्लॉक करते हैं। सिक्योर DNS चालू करने से आमतौर पर यह ठीक हो जाता है:",
  "Android: Settings > Network & internet > Private DNS > enter dns.google or one.one.one.one": "Android: सेटिंग्स > नेटवर्क और इंटरनेट > प्राइवेट DNS > dns.google या one.one.one.one डालें",
  "Chrome or Edge: Settings > Privacy and security > Use secure DNS": "Chrome या Edge: सेटिंग्स > प्राइवेसी और सिक्योरिटी > सिक्योर DNS इस्तेमाल करें",
  "Firefox: Settings > Privacy & Security > DNS over HTTPS > Increased protection": "Firefox: सेटिंग्स > प्राइवेसी और सिक्योरिटी > DNS over HTTPS > बढ़ी हुई सुरक्षा",
  "iPhone: install a secure DNS app such as Cloudflare 1.1.1.1": "iPhone: सिक्योर DNS वाला कोई ऐप इंस्टॉल करें, जैसे Cloudflare 1.1.1.1",
  "In Russia": "रूस में",
  "Smart Auto sends blocked photos and videos through our own servers, and friends who already have a post can pass it to you directly (peer sharing). This helps, but some blocks can't be avoided without a VPN, so we can't promise everything will load.": "स्मार्ट ऑटो ब्लॉक की गई फ़ोटो और वीडियो हमारे अपने सर्वर से भेजता है, और जिन दोस्तों के पास पोस्ट पहले से है, वे उसे सीधे आपको दे सकते हैं (पीयर शेयरिंग)। इससे मदद मिलती है, लेकिन कुछ रोक VPN के बिना नहीं हटतीं, इसलिए हम वादा नहीं कर सकते कि सब कुछ लोड होगा।",
