  "Open the app on your TV without typing a long address. It's free and takes about a minute.": "लंबा पता टाइप किए बिना अपने टीवी पर ऐप खोलें। यह मुफ़्त है और लगभग एक मिनट लगता है।",
  "Your TV link": "आपका टीवी लिंक",
