  "Which TV do you have?": "आपके पास कौन-सा टीवी है?",
  "Pick your TV to see the fastest way for it.": "अपना टीवी चुनें, ताकि उसके लिए सबसे तेज़ तरीका दिखे।",
  "After the first time": "पहली बार के बाद",
  "Bookmark the page in the TV browser, or pin it to the TV home screen. On Google TV and Android TV you can also install our TV app for its own icon.": "टीवी ब्राउज़र में पेज बुकमार्क करें या उसे टीवी की होम स्क्रीन पर पिन करें। Google TV और Android TV पर अपने आइकन के लिए हमारा टीवी ऐप भी इंस्टॉल कर सकते हैं।",
  "What a website can't do": "वेबसाइट क्या नहीं कर सकती",
  "Find your TV on the Wi-Fi and open its browser by itself. Only the TV maker's app can do that, which is why the steps use it.": "Wi-Fi पर खुद आपका टीवी ढूँढकर उसका ब्राउज़र खोलना। यह सिर्फ़ टीवी कंपनी का ऐप कर सकता है, इसीलिए ये स्टेप उसी का इस्तेमाल करते हैं।",
  "Screen mirroring (Smart View, AirPlay) only copies your phone's screen. It doesn't open the TV browser.": "स्क्रीन मिररिंग (Smart View, AirPlay) सिर्फ़ फ़ोन की स्क्रीन दिखाती है। यह टीवी ब्राउज़र नहीं खोलती।",
  "One-tap casting needs a paid Google registration, so we don't use it.": "एक टैप में कास्ट करने के लिए Google पर पैसे देकर रजिस्ट्रेशन चाहिए, इसलिए हम इसे इस्तेमाल नहीं करते।",
  "Copied. Now paste it on the TV with the steps below.": "कॉपी हो गया। अब नीचे दिए स्टेप से इसे टीवी पर पेस्ट करें।",
  "Copy didn't work. Type {host} on the TV instead.": "कॉपी नहीं हुआ। इसके बजाय टीवी पर {host} टाइप करें।",
