  "Mail settings": "मेल सेटिंग्स",
  "No mail yet": "अभी कोई मेल नहीं",
  "Mail that your filter moves into {folder} shows up here.": "आपका फ़िल्टर जो मेल {folder} में ले जाता है, वह यहाँ दिखेगा।",
  "Message not found": "संदेश नहीं मिला",
  "It may be older than this device keeps.": "हो सकता है यह इस डिवाइस में रखे गए समय से पुराना हो।",
  "Loading message…": "संदेश लोड हो रहा है…",
