  "Connect": "जोड़ें",
  "Service: {name}": "सेवा: {name}",
  "Folder: {folder}": "फ़ोल्डर: {folder}",
  "Codes only: on": "केवल कोड: चालू",
  "Codes only: off": "केवल कोड: बंद",
  "Maximum age: {n} days": "अधिकतम उम्र: {n} दिन",
  "Maximum age: any": "अधिकतम उम्र: कोई भी",
  "Read-only: moving, deleting and sending are off.": "केवल पढ़ना: खिसकाना, हटाना और भेजना बंद है।",
  "Change settings": "सेटिंग्स बदलें",
  "Disconnect and wipe mail": "डिस्कनेक्ट करें और मेल मिटाएँ",
  "Too many tries. Wait a minute and try again.": "बहुत ज़्यादा प्रयास। एक मिनट रुककर फिर कोशिश करें।",
  "SimpleLogin said no. Try again.": "SimpleLogin ने मना कर दिया। फिर कोशिश करें।",
  "This account uses a security key. Sign in with an API key instead.": "यह खाता सुरक्षा कुंजी इस्तेमाल करता है। API कुंजी से साइन इन करें।",
  "SimpleLogin signed this device out. Sign in again.": "SimpleLogin ने इस डिवाइस को साइन आउट कर दिया। फिर से साइन इन करें।",
  "Too many wrong codes. Ask for a new one.": "बहुत ज़्यादा गलत कोड। नया कोड माँगें।",
  "SimpleLogin didn't accept that API key.": "SimpleLogin ने वह API कुंजी स्वीकार नहीं की।",
  "SimpleLogin didn't offer an alias domain.": "SimpleLogin ने उपनाम के लिए कोई डोमेन नहीं दिया।",
  "A free SimpleLogin account gives you aliases: addresses you hand out instead of your real one.": "मुफ़्त SimpleLogin खाता आपको उपनाम देता है: ऐसे पते जिन्हें आप असली पते की जगह देते हैं।",
  "Mail to an alias forwards to your own mailbox. Your Mail filter can then move code emails into your ViktorychApp folder.": "उपनाम पर आया मेल आपके मेलबॉक्स में जाता है। फिर आपका मेल फ़िल्टर कोड वाले ईमेल ViktorychApp फ़ोल्डर में ले जा सकता है।",
  "Sign-up and sign-in happen right here. Your password goes only to SimpleLogin and is never stored; the key it returns stays encrypted on this device.": "साइन अप और साइन इन यहीं होते हैं। आपका पासवर्ड केवल SimpleLogin को जाता है और कहीं सहेजा नहीं जाता; मिली कुंजी इस डिवाइस पर एन्क्रिप्ट रहती है।",
  "Create free account": "मुफ़्त खाता बनाएँ",
