  "Link your own SMSPool account to see your codes here.": "यहाँ अपने कोड देखने के लिए अपना SMSPool खाता जोड़ें।",
  "Paste a fresh key from your SMSPool settings.": "SMSPool सेटिंग्स से नई कुंजी पेस्ट करें।",
  "SMSPool settings": "SMSPool सेटिंग्स",
  "Paste the API key from your SMSPool account settings.": "अपने SMSPool खाते की सेटिंग्स से API कुंजी पेस्ट करें।",
  "The key is kept encrypted on this device. It passes through our relay only for each read, and the relay keeps nothing.": "कुंजी इस डिवाइस पर एन्क्रिप्ट होकर रहती है। यह हर बार पढ़ते समय ही हमारे रिले से गुज़रती है, और रिले कुछ नहीं रखता।",
  "Read-only: the app never buys, cancels or refunds numbers.": "केवल पढ़ना: ऐप कभी नंबर नहीं खरीदता, रद्द नहीं करता और रिफ़ंड नहीं करता।",
  "SMSPool API key": "SMSPool API कुंजी",
