  "Paste a public Spotify playlist link. Each song is matched on YouTube and saved as a playlist here.": "किसी सार्वजनिक Spotify प्लेलिस्ट का लिंक चिपकाएं। हर गाना YouTube पर ढूंढकर यहाँ प्लेलिस्ट के रूप में सेव होगा।",
  "Phones may still stop YouTube in the background; iPhone and iPad always do. Lyrics aren’t shown: there is no free licensed source.": "फ़ोन बैकग्राउंड में YouTube को फिर भी रोक सकते हैं; iPhone और iPad हमेशा रोकते हैं। बोल नहीं दिखते: कोई मुफ़्त लाइसेंस वाला स्रोत नहीं है।",
  "Play a song, or use Add to queue on any song.": "कोई गाना चलाएं, या किसी भी गाने पर कतार में जोड़ें चुनें।",
