  "Sign in to YouTube for Premium: no ads, 256 kbps audio and the best quality your account allows.": "Premium के लिए YouTube में साइन इन करें: बिना विज्ञापन, 256 kbps ऑडियो और आपके खाते के हिसाब से सबसे अच्छी गुणवत्ता।",
