  "Step 1 · Open Discord": "चरण 1 · Discord खोलें",
  "Sign in with a SPARE account, not your main one. Discord may lock accounts used this way.": "मुख्य अकाउंट नहीं, एक स्पेयर अकाउंट से साइन इन करें। Discord ऐसे इस्तेमाल किए गए अकाउंट लॉक कर सकता है।",
