  "Step 2 · Copy your key": "चरण 2 · अपनी की कॉपी करें",
  "This step needs a desktop browser. Open this page on a computer to copy the key, or paste a key you already have.": "इस चरण के लिए डेस्कटॉप ब्राउज़र चाहिए। की कॉपी करने के लिए यह पेज कंप्यूटर पर खोलें, या जो की आपके पास है उसे पेस्ट करें।",
  "In the Discord tab, open the developer console: F12, or Ctrl+Shift+I (Cmd+Option+I on a Mac).": "Discord टैब में डेवलपर कंसोल खोलें: F12, या Ctrl+Shift+I (Mac पर Cmd+Option+I)।",
  "Copy the snippet below, paste it into the console and press Enter.": "नीचे दिया स्निपेट कॉपी करें, कंसोल में पेस्ट करें और Enter दबाएँ।",
  "It copies your key to the clipboard. Come back here and paste it in the next step.": "यह आपकी की क्लिपबोर्ड पर कॉपी करता है। यहाँ वापस आकर अगले चरण में पेस्ट करें।",
  "What it does: it reads your own account's key and copies it to your clipboard. It is not sent anywhere.": "यह क्या करता है: आपके अपने अकाउंट की की पढ़कर क्लिपबोर्ड पर कॉपी करता है। कहीं नहीं भेजी जाती।",
  "Console snippet": "कंसोल स्निपेट",
  "Copy snippet": "स्निपेट कॉपी करें",
  "Discord will show a red “Self-XSS” warning.": "Discord एक लाल “Self-XSS” चेतावनी दिखाएगा।",
  "That warning is there because pasting code someone else gives you can hand them your account. This snippet is safe only because you can read exactly what it does above. Never paste code you do not understand.": "यह चेतावनी इसलिए है क्योंकि कोई और जो कोड दे उसे पेस्ट करने से आपका अकाउंट उसके हाथ लग सकता है। यह स्निपेट सिर्फ़ इसलिए सुरक्षित है क्योंकि आप ऊपर ठीक-ठीक पढ़ सकते हैं कि यह क्या करता है। जो कोड न समझें उसे कभी पेस्ट न करें।",
  "Step 3 · Paste your key": "चरण 3 · अपनी की पेस्ट करें",
  "Paste the key you copied. It is checked straight from this device and kept here only.": "आपने जो की कॉपी की उसे पेस्ट करें। इसे इसी डिवाइस से जाँचा जाता है और सिर्फ़ यहीं रखा जाता है।",
  "Your spare account": "आपका स्पेयर अकाउंट",
  "Check key": "की जाँचें",
