  "Couldn’t post to NZlay. Your text is still here.": "NZlay पर पोस्ट नहीं हो सका। आपका टेक्स्ट यहीं है।",
  "Couldn’t reach NZlay. Try again.": "NZlay तक नहीं पहुँच सके। फिर से कोशिश करें।",
