  "NZlay doesn’t let this account post here.": "NZlay इस खाते को यहाँ पोस्ट करने नहीं देता।",
  "NZlay forum": "NZlay फ़ोरम",
  "NZlay forum ReGone links": "NZlay फ़ोरम के ReGone लिंक",
  "NZlay forum community": "NZlay फ़ोरम समुदाय",
  "NZlay forum posting": "NZlay फ़ोरम पर पोस्ट करना",
  "NZlay has no sign-in for other apps, so you sign in with your NZlay email and password here. Your password goes once to NZlay and is never kept. The NZlay session that comes back is encrypted and kept only in this browser. Posts go out only when you tap Post or Reply.": "NZlay के पास अन्य ऐप्स के लिए साइन-इन नहीं है, इसलिए आप यहाँ अपने NZlay ईमेल और पासवर्ड से साइन इन करते हैं। आपका पासवर्ड एक बार NZlay को जाता है और कभी नहीं रखा जाता। लौटा हुआ NZlay सत्र एन्क्रिप्ट होकर केवल इसी ब्राउज़र में रखा जाता है। पोस्ट तभी जाती हैं जब आप पोस्ट या जवाब टैप करते हैं।",
  "NZlay isn’t answering right now.": "NZlay अभी जवाब नहीं दे रहा।",
  "NZlay member": "NZlay सदस्य",
  "NZlay says that session is signed out.": "NZlay कहता है कि वह सत्र साइन-आउट है।",
  "NZlay sign-in is turned off.": "NZlay साइन-इन बंद है।",
  "NZlay signed you out. Sign in again.": "NZlay ने आपको साइन-आउट कर दिया। फिर से साइन इन करें।",
  "NZlay wants to check that you’re a person. Sign in on NZlay, solve its check there, then come back and paste your session below.": "NZlay पुष्टि करना चाहता है कि आप व्यक्ति हैं। NZlay पर साइन इन करें, वहाँ उसकी जाँच पूरी करें, फिर लौटकर अपना सत्र नीचे पेस्ट करें।",
  "NZlay wants to check that you’re a person. Your text is copied; finish on NZlay.": "NZlay पुष्टि करना चाहता है कि आप व्यक्ति हैं। आपका टेक्स्ट कॉपी हो गया; NZlay पर पूरा करें।",
  "News, help, clans and the players behind ReGone.": "समाचार, मदद, क्लैन और ReGone के खिलाड़ी।",
  "No NZlay account?": "NZlay खाता नहीं है?",
  "Open NZlay": "NZlay खोलें",
  "Open on NZlay": "NZlay पर खोलें",
  "Open the forum": "फ़ोरम खोलें",
