  "Posting…": "पोस्ट हो रहा है…",
  "Posts come straight from nzlay.com. Replies you send go to NZlay as you.": "पोस्ट सीधे nzlay.com से आती हैं। आपके जवाब आपके रूप में NZlay पर जाते हैं।",
  "Posts to NZlay": "NZlay पर पोस्ट करता है",
  "Posts to NZlay as {name}": "{name} के रूप में NZlay पर पोस्ट करता है",
