  "Session": "सत्र",
  "Sign in to NZlay": "NZlay में साइन इन करें",
  "Sign in with your NZlay account to post and reply here.": "यहाँ पोस्ट और जवाब देने के लिए अपने NZlay खाते से साइन इन करें।",
