  "Data saver is on. This is a big download.": "डेटा सेवर चालू है। यह बड़ा डाउनलोड है।",
  "This device is low on memory. The model may be slow or fail; Instant always works.": "इस डिवाइस में मेमोरी कम है। मॉडल धीमा चल सकता है या फ़ेल हो सकता है; तुरंत मोड हमेशा चलता है।",
  "You're on mobile data. Wi-Fi is better for this.": "आप मोबाइल डेटा पर हैं। इसके लिए Wi-Fi बेहतर है।",
