  "The Local AI page that changes settings from plain words. Models run on each person's device; nothing is sent to us.": "लोकल AI पेज जो आसान शब्दों से सेटिंग बदलता है। मॉडल हर व्यक्ति के डिवाइस पर चलते हैं; हमें कुछ नहीं भेजा जाता।",
  "A round button on every page that opens Local AI.": "हर पेज पर एक गोल बटन जो लोकल AI खोलता है।",
  "Ask Local AI": "लोकल AI से पूछें",
  "Say what you want changed, like “bigger text” or “make it private”. It runs on this device.": "बताएँ क्या बदलना है, जैसे “बड़ा टेक्स्ट” या “प्राइवेट कर दो”। यह इसी डिवाइस पर चलता है।",
  "Local AI is turned off right now.": "लोकल AI अभी बंद है।",
