  "Photos and short clips from posts you have seen on this TV, with their text. They stay on the TV.": "इस TV पर देखी गई पोस्ट की तस्वीरें और छोटी क्लिप, उनके टेक्स्ट के साथ। ये TV पर ही रहती हैं।",
