  "Preview as person, like @name": "व्यक्ति के रूप में पूर्वावलोकन, जैसे @name",
  "Main": "मुख्य",
  "Each person sees exactly one of your display names. The most specific audience wins: a person, then a list, then friends, then followers, then public. If a name is hidden from someone, they see a broader one.": "हर व्यक्ति आपका ठीक एक डिस्प्ले नाम देखता है। सबसे खास दर्शक जीतता है: व्यक्ति, फिर सूची, फिर दोस्त, फिर फ़ॉलोअर्स, फिर सार्वजनिक। अगर कोई नाम किसी से छिपा है, तो वे उससे व्यापक नाम देखते हैं।",
  "Nicknames people give you privately still win in their own view.": "लोग आपको निजी तौर पर जो उपनाम देते हैं, वे उनके अपने दृश्य में ही प्राथमिक रहते हैं।",
  "New display name": "नया डिस्प्ले नाम",
  "New names start visible to friends only.": "नए नाम शुरू में केवल दोस्तों को दिखते हैं।",
  "Remove this display name?": "यह डिस्प्ले नाम हटाएँ?",
  "Quick settings": "झटपट सेटिंग्स",
  "+{n} more at 10 different people · up to {cap} a day": "10 अलग-अलग लोगों पर +{n} और · दिन में अधिकतम {cap}",
  "+{n} once": "+{n} एक बार",
  "+{n} once they stay a week, post and keep a streak · up to {cap} a day": "+{n} जब वे एक हफ़्ता रुकें, पोस्ट करें और स्ट्रीक बनाए रखें · दिन में अधिकतम {cap}",
  "+{n} when 3 different people reply or like · up to {cap} a day": "+{n} जब 3 अलग-अलग लोग जवाब दें या लाइक करें · दिन में अधिकतम {cap}",
