  "Viktorychs are earned by real effort and are never sold. They have no cash value and can only be spent on gifts and stickers.": "Viktorychs असली मेहनत से कमाए जाते हैं और कभी बेचे नहीं जाते। इनका कोई नकद मूल्य नहीं है और इन्हें सिर्फ़ गिफ़्ट और स्टिकर पर खर्च किया जा सकता है।",
  "Viktorychs earned through abuse, such as fake accounts or self-engagement, can be removed.": "दुरुपयोग से कमाए गए Viktorychs, जैसे नकली अकाउंट या खुद से एंगेजमेंट, हटाए जा सकते हैं।",
  "Viktorychs have no cash value and can’t be refunded once spent.": "Viktorychs का कोई नकद मूल्य नहीं है और खर्च होने के बाद ये वापस नहीं होते।",
  "Viktorychs have no cash value. They can’t be bought, cashed out or transferred for money, and they can’t be refunded once spent.": "Viktorychs का कोई नकद मूल्य नहीं है। इन्हें खरीदा, कैश आउट या पैसे के बदले ट्रांसफ़र नहीं किया जा सकता, और खर्च होने के बाद ये वापस नहीं होते।",
