  "You can pay for an item with money, through our payment provider, or with Viktorychs. Viktorychs are earned by taking part and are never sold.": "आप किसी आइटम के लिए पैसे से, हमारे पेमेंट प्रोवाइडर के ज़रिए, या Viktorychs से पेमेंट कर सकते हैं। Viktorychs भाग लेकर कमाए जाते हैं और कभी बेचे नहीं जाते।",
  "You can’t send gifts to someone who blocked you or who doesn’t accept gifts from you. Gifting is rate-limited to stop spam.": "आप उसे गिफ़्ट नहीं भेज सकते जिसने आपको ब्लॉक किया है या जो आपसे गिफ़्ट नहीं लेता। स्पैम रोकने के लिए गिफ़्ट भेजने की सीमा है।",
