  "People you lock still see you as a follower. The app owner can review locked follows for safety; every look is logged. Your code is never shown to anyone.": "जिन्हें आप लॉक करते हैं वे आपको अब भी फ़ॉलोअर के रूप में देखते हैं। ऐप का मालिक सुरक्षा के लिए लॉक्ड फ़ॉलो देख सकता है; हर बार देखना लॉग होता है। आपका कोड कभी किसी को नहीं दिखाया जाता।",
